package com.companion.ai.context;
import com.companion.ai.MemoryEngine; import com.companion.ai.config.LlmProperties; import com.companion.ai.growth.GrowthEvaluationContext; import com.companion.ai.prompt.ChatPromptComposer; import com.companion.character.snapshot.CharacterSnapshot; import com.companion.entity.CharacterRelationship; import com.companion.mapper.ChatMessageMapper; import com.companion.service.*; import org.junit.jupiter.api.Test; import java.util.Optional; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.Mockito.*;
class GrowthContextWiringTest { @Test void usesFrozenSnapshotAndCharacterScopedRelationshipAndMemory(){MemoryEngine memory=mock(MemoryEngine.class);ConversationContextManager limiter=mock(ConversationContextManager.class);CharacterRelationshipService relationships=mock(CharacterRelationshipService.class);when(memory.getMemoryContext(10L,71L,"user message")).thenReturn("A-memory");when(limiter.limitMemory("A-memory")).thenReturn("bounded-A-memory");CharacterRelationship r=new CharacterRelationship();r.setStage("TRUSTED");r.setSummary("A-relationship");when(relationships.get(10L,71L)).thenReturn(Optional.of(r));ChatContextAssembler assembler=new ChatContextAssembler(memory,limiter,mock(ChatMessageMapper.class),mock(ChatPromptComposer.class),new LlmProperties(),relationships,mock(CharacterGrowthService.class));GrowthEvaluationContext c=assembler.growthEvaluationContext(10L,snapshot(),"user message","assistant response");assertThat(c.characterIdentity()).contains("Frozen Nova","Frozen personality","Frozen background","Frozen goal","Frozen style");assertThat(c.relationship()).contains("A-relationship");assertThat(c.memory()).isEqualTo("bounded-A-memory");assertThat(c.userMessage()).isEqualTo("user message");assertThat(c.assistantResponse()).isEqualTo("assistant response");verify(memory).getMemoryContext(10L,71L,"user message");verify(relationships).get(10L,71L);verify(memory,never()).getMemoryContext(anyLong(),eq(72L),anyString());}
 private CharacterSnapshot snapshot(){return new CharacterSnapshot(1,71L,"AI","Frozen Nova",null,"Frozen identity","Frozen personality","Frozen goal","Frozen background","Frozen relationship","Frozen style",CharacterSnapshot.Profile.empty(),"INITIAL",null,null,"purple");}}
